# Substrate §3.1 — Veracity Gate.
try:
    from proactive.middleware import veracity_gate
except ImportError:
    import sys, os
    sys.path.insert(0, os.path.join(os.getcwd(), 'app'))
    from proactive.middleware import veracity_gate
env    = dict(input) if isinstance(input, dict) else {"raw": input}
output = veracity_gate(env)

# Substrate §3.1 — Privacy / Redaction Gate.
try:
    from proactive.middleware import privacy_gate
except ImportError:
    import sys, os
    sys.path.insert(0, os.path.join(os.getcwd(), 'app'))
    from proactive.middleware import privacy_gate
env    = dict(input) if isinstance(input, dict) else {"raw": input}
output = privacy_gate(env)

# Substrate §3.1 — Adversarial-Input Filter.
try:
    from proactive.middleware import adversarial_gate
except ImportError:
    import sys, os
    sys.path.insert(0, os.path.join(os.getcwd(), 'app'))
    from proactive.middleware import adversarial_gate
env    = dict(input) if isinstance(input, dict) else {"raw": input}
output = adversarial_gate(env)

# Conscious — Parse Agent Response (M5.4 agent_flow variant).
# Reads the agent_flow output (`{request, response}`) and the env that
# was stashed by the Build Prompt node, maps the agent's reply
# (TRANSFER / NOTIFY / NONE) to a structured intent, emits the env so
# downstream Substrate stages see the same shape as the deterministic /
# transport-based slices. Provenance records the raw text for audit.
env = variables.pop("__conscious_env__", None) or {}
if not isinstance(env, dict):
    env = {"raw": env}
obs = env.get("observation") or {}

reply       = input if isinstance(input, dict) else {}
agent_resp  = reply.get("response")
if isinstance(agent_resp, dict):
    text = str(agent_resp.get("content") or agent_resp.get("text") or "")
elif isinstance(agent_resp, str):
    text = agent_resp
else:
    text = str(agent_resp or "")
verdict = text.upper()

intent = None
if "TRANSFER" in verdict:
    intent = {"capability": "core.transfer_funds",
              "rationale":  "Conscious agent flagged high-stake action"}
elif "NOTIFY" in verdict:
    intent = {"capability": "core.notify",
              "rationale":  "Conscious agent proposed low-stake nudge",
              "args":       {"message": f"Heads up: {obs.get('subject')}"}}
# else NONE / unrecognised -> no intent emitted; downstream sees None

if intent:
    env["intent"] = intent
env.setdefault("provenance", []).append({
    "stage":          "conscious_anticipate_agent_flow",
    "agent_text":     text[:200],
    "emitted_intent": (intent or {}).get("capability"),
})
output = env

# Substrate §3.4 — Capability Registry.
env  = dict(input) if isinstance(input, dict) else {"raw": input}
caps = variables.setdefault("capabilities", {})
if not caps:
    caps["core.notify"] = {
        "name": "core.notify", "purpose": "Surface a UI notification",
        "scopes": ["read-only"], "latency_tier": "interactive", "cost_estimate": 0.0,
    }
    caps["core.send_email"] = {
        "name": "core.send_email", "purpose": "Send an outbound email",
        "scopes": ["write", "external-network", "affects-third-party"],
        "latency_tier": "responsive", "cost_estimate": 0.001,
    }
    caps["core.transfer_funds"] = {
        "name": "core.transfer_funds", "purpose": "Initiate a money transfer",
        "scopes": ["spends-money", "write", "affects-third-party"],
        "latency_tier": "responsive", "cost_estimate": 0.5,
    }
intent   = env.get("intent") or {}
cap_name = intent.get("capability")
if cap_name and cap_name in caps:
    cap = caps[cap_name]
    env["resolved_capability"] = {
        "name": cap_name, "scopes": cap["scopes"], "latency_tier": cap["latency_tier"],
    }
    env["scopes"] = sorted(set(list(env.get("scopes", [])) + list(cap["scopes"])))
    env.setdefault("provenance", []).append({"stage": "capability_registry", "resolved": cap_name})
else:
    env.setdefault("provenance", []).append({"stage": "capability_registry", "resolved": None})
output = env

# Substrate §3.5 — Governor.
env    = dict(input) if isinstance(input, dict) else {"raw": input}
scopes = list(env.get("scopes", ["read-only"]))
conf   = float(env.get("confidence", 1.0))

HIGH_STAKE = {"spends-money", "impersonates-user", "affects-third-party"}
WRITE      = {"write"}

has_high  = False
has_write = False
for s in scopes:
    if s in HIGH_STAKE: has_high  = True
    if s in WRITE:      has_write = True

if has_high:
    decision, reason = "consent_required", "high-stake scope present"
elif has_write and conf < 0.85:
    decision, reason = "consent_required", "write at low confidence"
else:
    decision, reason = "allow", "low-class action"

env["governor_verdict"] = {
    "decision":   decision,
    "reason":     reason,
    "scopes":     scopes,
    "confidence": conf,
}
output = env
